import unittest
from logic import solve

class TestSolve(unittest.TestCase):
    def test_reproduction_case(self):
        cases = {'orders': [{'id': 'b', 'updatedAt': 1, 'status': 'open'}, {'id': 'b', 'updatedAt': 3, 'status': 'cancelled'}, {'id': 'a', 'updatedAt': 2, 'status': 'open'}]}
        expected = ['a']
        self.assertEqual(solve(cases), expected)

    def test_empty_orders(self):
        self.assertEqual(solve({'orders': []}), [])

    def test_single_order_open(self):
        self.assertEqual(solve({'orders': [{'id': 'a', 'updatedAt': 1, 'status': 'open'}]}), ['a'])

    def test_single_order_cancelled(self):
        self.assertEqual(solve({'orders': [{'id': 'a', 'updatedAt': 1, 'status': 'cancelled'}]}), [])

    def test_tie_updatedAt(self):
        # Ties choose the later input record
        cases = {'orders': [
            {'id': 'b', 'updatedAt': 1, 'status': 'open'},
            {'id': 'b', 'updatedAt': 1, 'status': 'cancelled'}
        ]}
        self.assertEqual(solve(cases), [])

        cases2 = {'orders': [
            {'id': 'b', 'updatedAt': 1, 'status': 'cancelled'},
            {'id': 'b', 'updatedAt': 1, 'status': 'open'}
        ]}
        self.assertEqual(solve(cases2), ['b'])

    def test_different_updatedAt(self):
        # Each id uses the greatest updatedAt timestamp
        cases = {'orders': [
            {'id': 'b', 'updatedAt': 2, 'status': 'open'},
            {'id': 'b', 'updatedAt': 1, 'status': 'cancelled'}
        ]}
        self.assertEqual(solve(cases), ['b'])

    def test_multiple_orders(self):
        cases = {'orders': [
            {'id': 'c', 'updatedAt': 1, 'status': 'open'},
            {'id': 'a', 'updatedAt': 1, 'status': 'open'},
            {'id': 'b', 'updatedAt': 1, 'status': 'open'}
        ]}
        self.assertEqual(solve(cases), ['a', 'b', 'c'])

if __name__ == '__main__':
    unittest.main()
